<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Foundry\SubordinatePersonaAssemblyService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:foundry:assemble-subordinate-persona',description:'Assemble one exact subordinate Persona candidate from complementary sealed section packets')]
final class FoundryAssembleSubordinatePersonaCommand extends Command{public function __construct(private readonly SubordinatePersonaAssemblyService$service){parent::__construct();}protected function configure():void{$this->addArgument('specification-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->service->assemble((string)$i->getArgument('specification-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$i->getOption('json')){$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$o->writeln('<info>SUBORDINATE_PERSONA_CANDIDATE_ASSEMBLED</info> '.$r['candidate_id']);$o->writeln('Persona: '.$r['persona_name']);$o->writeln('Status: '.$r['status']);$o->writeln('Section packets: '.count($r['section_products']));$o->writeln('Persona approval authority: NOT GRANTED');$o->writeln('Profile approval authority: NOT GRANTED');$o->writeln('Spawning authority: NOT GRANTED');$o->writeln('Admission authority: NOT GRANTED');$o->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
